# name: lag1_response_autocorrelation
# description: Correlation between a participant's rating on consecutive trials (pairs within the same session only); observed > null means sequential response perseveration/assimilation the trial-independent model does not produce (observed < null means alternation).
def test_statistic(df):
    t = df["trial_index"].values
    r = df["rating"].values.astype(float)
    ok = np.diff(t) == 1
    a, b = r[:-1][ok], r[1:][ok]
    if len(a) < 3 or a.std() == 0 or b.std() == 0:
        return 0.0
    return float(np.corrcoef(a, b)[0, 1])

# name: within_session_yes_drift
# description: Yes rate on trials in the second half of each session (trial_index >= 225) minus the first half; nonzero observed vs null ~0 means participants become more (positive) or less (negative) liberal over the session, which the stationary model cannot produce.
def test_statistic(df):
    t = df["trial_index"].values
    r = df["rating"].values.astype(float)
    late = t >= 225
    if late.sum() == 0 or (~late).sum() == 0:
        return 0.0
    return float(r[late].mean() - r[~late].mean())

# name: participant_yes_rate_sd
# description: SD across participants (rows are in session order; a new participant starts where trial_index resets to 0) of each participant's overall yes rate; observed > null means people differ in response bias/generalization breadth more than the single shared-parameter model produces.
def test_statistic(df):
    pid = (df["trial_index"].values == 0).cumsum()
    r = df["rating"].values.astype(float)
    rates = pd.Series(r).groupby(pid).mean()
    if len(rates) < 2:
        return 0.0
    return float(rates.std(ddof=0))

# name: yes_rate_target_is_example
# description: Yes rate on trials where the target is itself one of the shown examples; observed > null means people endorse already-seen examples more reliably than the model's noisy-example/tempered posterior predicts (observed < null means less).
def test_statistic(df):
    ex = df["number_set"].astype(str).str.split(",", expand=True).apply(pd.to_numeric, errors="coerce").values
    tg = df["target"].astype(int).values
    hit = (ex == tg[:, None]).any(axis=1)
    if hit.sum() == 0:
        return 0.0
    return float(df["rating"].values[hit].mean())
